import {language,setLanguage} from './ui.mjs';
import {translate} from './locale-text.mjs';
const textHistory=new WeakMap(),attributeHistory=new WeakMap();let queued=false;
function rewriteText(node){if(node.parentElement?.closest('script,style,code,pre,[data-language-toggle],.brand,.phone-home h1'))return;const current=node.data,old=textHistory.get(node),source=old&&current===old.last?old.source:current;const next=language==='zh'?translate(source):source;if(next!==current)node.data=next;textHistory.set(node,{source,last:next});}
function rewriteAttribute(el,key){if(el.matches('[data-language-toggle]'))return;const current=el.getAttribute(key);if(!current)return;let records=attributeHistory.get(el);if(!records){records={};attributeHistory.set(el,records);}const old=records[key],source=old&&current===old.last?old.source:current;const next=language==='zh'?translate(source):source;if(next!==current)el.setAttribute(key,next);records[key]={source,last:next};}
export function refreshLocale(){queued=false;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode())rewriteText(node);for(const el of document.querySelectorAll('[title],[aria-label],[placeholder],[alt]'))for(const key of ['title','aria-label','placeholder','alt'])rewriteAttribute(el,key);document.documentElement.lang=language==='zh'?'zh-CN':'en';const title=document.querySelector('title');if(title?.firstChild)rewriteText(title.firstChild);const control=document.querySelector('[data-language-toggle]');if(control){const label=language==='zh'?'EN':'中文',hint=language==='zh'?'切换为英语':'Switch to Chinese';if(control.textContent!==label)control.textContent=label;if(control.getAttribute('aria-label')!==hint)control.setAttribute('aria-label',hint);if(control.title!==hint)control.title=hint;}}
function schedule(){if(!queued){queued=true;queueMicrotask(refreshLocale);}}
const toggle=document.createElement('button');toggle.type='button';toggle.className='language-toggle';toggle.dataset.languageToggle='';(document.querySelector('.connected-wallet-control')||document.querySelector('#wallet-connect')).before(toggle);
toggle.onclick=()=>{const values=[...document.querySelectorAll('#app input')].map(e=>({id:e.id,value:e.value}));setLanguage(language==='zh'?'en':'zh');window.dispatchEvent(new CustomEvent('fillout:language'));for(const item of values){const input=document.getElementById(item.id);if(input)input.value=item.value;}refreshLocale();};
new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['title','aria-label','placeholder','alt']});
document.addEventListener('invalid',event=>{const input=event.target;if(typeof input.setCustomValidity!=='function')return;if(language==='zh')input.setCustomValidity(input.validity.valueMissing?'请填写此字段。':'请输入有效内容。');},true);
document.addEventListener('input',event=>event.target.setCustomValidity?.(''),true);
window.filloutLocaleAudit=()=>{const list=[];const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement?.closest('script,style,code,pre,[data-language-toggle],.brand,.phone-home h1'))continue;const value=node.data.trim();if(!/[A-Za-z]{2,}/.test(value)||!node.parentElement?.getClientRects().length)continue;const stripped=value.replace(/https?:\/\/\S+|0x[a-fA-F0-9]+|\b(?:FILLOUT|FillOut|OpenBook|VRAM|ETH|EVM|JSON|API|NFT|NAND|ACDV|GitHub|MetaMask|OKX|Bitget|TapeOut|Behemoth|BEM|Robinhood|wei|Ctrl|Cmd|X)\b/g,'');if(/[A-Za-z]{2,}/.test(stripped))list.push(value);}return [...new Set(list)];};
refreshLocale();
